with target as(select isbn13,content_hash,candidate||jsonb_build_object('cover_url','https://www.hakusensha.co.jp/wp_hakusensha/postimage/2016/lists/9784592191735.jpg','cover_hash','4e3c64f26810456b0fceb0451d50f4e8d07f39028d166fcd5a06ba92b8e377f1','source_url','https://www.hakusensha.co.jp/comicslist/45177/','cover_reference_before_correction',jsonb_build_object('cover_url',candidate->>'cover_url','cover_hash',candidate->>'cover_hash','source_url',candidate->>'source_url')) as new_candidate from public.book_content_review_jobs where isbn13='9784592191735' and content_hash='253479a0e5bb38303b6d4a7f1806eb320bf02092ddc1978fce03f986d030b8fd' and adult_only is null and status='pending_review' and cover_status='unreviewed'),fixed as(update public.book_content_review_jobs j set candidate=t.new_candidate,content_hash=encode(sha256(convert_to(t.new_candidate::text,'UTF8')),'hex'),reason='文字のみの代替画像を、ISBN一致の白泉社公式表紙へ修正。分類・公開許可は維持。',updated_at=now() from target t where j.isbn13=t.isbn13 and j.content_hash=t.content_hash returning j.isbn13,j.candidate),confirmed as(insert into public.book_metadata_overrides(isbn,normalized_isbn,title,series_title,series_key,volume_number,author,publisher,description,thumbnail_url,source_url,source,enabled) select isbn13,isbn13,'学園ベビーシッターズ 3','学園ベビーシッターズ','学園ベビーシッターズ',3,'時計野はり','白泉社',candidate->>'description','https://www.hakusensha.co.jp/wp_hakusensha/postimage/2016/lists/9784592191735.jpg','https://www.hakusensha.co.jp/comicslist/45177/','developer',true from fixed on conflict(normalized_isbn) where normalized_isbn is not null do nothing returning normalized_isbn) select (select count(*) from fixed) as corrected,(select count(*) from confirmed) as confirmed;
